if(!ctx.input||Array.isArray(ctx.input)||typeof ctx.input!=='object'||Object.keys(ctx.input).length)throw new Error('This action takes no input.');var totals={},coins=0,copper=0;for(var i=0;i<ORDER.length;i++)totals[ORDER[i]]={denomination:ORDER[i],count:0,copperValue:0,totalCopperValue:0};visit(root);var rows=[];for(var k=0;k<ORDER.length;k++){var row=totals[ORDER[k]];if(row.count){row.totalCopperValue=multiply(row.count,row.copperValue);rows.push(row);}}return {narration:'Physical currency beneath '+root.name+' is worth '+copper+' copper pieces.',effects:[],events:[],notifications:[],data:{rootId:root.id,coinCount:coins,copperValue:copper,denominations:rows,boundedDepth:4}};
